        exercises: [
          { type: "mcq", prompt: "Sue asks: \"Does this dress look OK?\" You don't like it. What is the tactful answer?", promptAr: "تسأل سو: \"هل يبدو هذا الفستان جيداً؟\" وأنت لا يعجبك. ما الجواب اللبق؟", options: ["No, it looks terrible.", "Well, I think darker colours suit you better.", "I hate this dress.", "Why did you buy it?"], answer: 1, explainAr: "نتجنب الكلام السلبي المباشر ونقول: I think darker colours suit you better." },
          { type: "mcq", prompt: "Your aunt invites you to a party, but you really don't want to go. What do you say tactfully?", promptAr: "تدعوك عمتك إلى حفلة، لكنك لا تريد الذهاب حقاً. ماذا تقول بلباقة؟", options: ["I don't want to come.", "Your parties are boring.", "We were planning to go to the cinema tomorrow.", "No, thanks. I'm busy with better things."], answer: 2, explainAr: "صيغة الماضي We were planning to… تخفّف الرفض وتجعله مهذباً." },
          { type: "mcq", prompt: "Your partner has taken you to the cinema as a birthday present. You didn't like the film. What do you say?", promptAr: "أخذك شريكك إلى السينما هدية عيد ميلادك، ولم يعجبك الفيلم. ماذا تقول؟", options: ["I've seen better performances.", "It was the worst film ever!", "You chose a stupid film.", "I wasted my birthday."], answer: 0, explainAr: "نعبّر عن عدم الإعجاب دون كلمات سلبية: I've seen better performances." },
          { type: "mcq", prompt: "Your friend is excited about a CD he's bought, which you really dislike. Give your reaction tactfully.", promptAr: "صديقك متحمس لقرص CD اشتراه، وأنت لا يعجبك أبداً. عبّر عن رأيك بلباقة.", options: ["That singer is awful.", "Throw it away!", "What a bad CD!", "Honestly, I've heard better singers."], answer: 3, explainAr: "نستخدم ظرف الموقف Honestly ونتجنب السلبية المباشرة: Honestly, I've heard better singers." },
          { type: "mcq", prompt: "Which way of softening is used in \"Unfortunately, the food was salty.\"?", promptAr: "أي طريقة لتخفيف الرسالة مستخدمة في \"Unfortunately, the food was salty.\"؟", options: ["Past forms", "Modal", "Not sounding negative", "Adverbs of attitude"], answer: 3, explainAr: "Unfortunately ظرف يعبّر عن موقف المتكلم (Adverbs of attitude)." },
          { type: "mcq", prompt: "Which way of softening is used in \"It could have been a bit hotter.\"?", promptAr: "أي طريقة لتخفيف الرسالة مستخدمة في \"It could have been a bit hotter.\"؟", options: ["Modal", "Past forms", "Adverbs of attitude", "Not sounding negative"], answer: 0, explainAr: "could have been فعل ناقص (Modal) يجعل النقد لطيفاً." },
          { type: "mcq", prompt: "Which way of softening is used in \"We were planning to go to the cinema tomorrow.\"?", promptAr: "أي طريقة لتخفيف الرسالة مستخدمة في \"We were planning to go to the cinema tomorrow.\"؟", options: ["Modal", "Past forms", "Adverbs of attitude", "Not sounding negative"], answer: 1, explainAr: "استخدمنا الماضي المستمر were planning مع أن الحديث عن الغد، وهذه صيغة ماضٍ للتلطيف (Past Forms)." },
          { type: "mcq", prompt: "Which way of softening is used in \"I think darker colours suit you better.\"?", promptAr: "أي طريقة لتخفيف الرسالة مستخدمة في \"I think darker colours suit you better.\"؟", options: ["Past forms", "Adverbs of attitude", "Not sounding negative", "Modal"], answer: 2, explainAr: "لم يقل «هذا اللون سيئ» بل قال رأياً إيجابياً: Not sounding negative." },
          { type: "fill", prompt: "___, I've heard better singers.", promptAr: "___، لقد سمعتُ مغنّين أفضل.", promptArFull: "بصراحة، لقد سمعتُ مغنّين أفضل.", options: ["Honest", "Honestly", "Honesty"], answer: 1, explainAr: "نحتاج ظرف موقف في بداية الجملة: Honestly (بصراحة)." },
          { type: "fill", prompt: "I'd go for black instead if I ___ you.", promptAr: "لو ___ مكانك لاخترتُ الأسود بدلاً منه.", promptArFull: "لو كنتُ مكانك لاخترتُ الأسود بدلاً منه.", options: ["am", "will be", "were"], answer: 2, explainAr: "العبارة الثابتة للنصيحة اللبقة: if I were you." },
          { type: "fill", prompt: "It could have ___ a bit hotter.", promptAr: "كان يمكن أن ___ أسخن قليلاً.", promptArFull: "كان يمكن أن يكون أسخن قليلاً.", options: ["been", "be", "being"], answer: 0, explainAr: "بعد could have نستخدم التصريف الثالث: been." },
          { type: "fill", prompt: "We ___ planning to go to the cinema tomorrow.", promptAr: "___ نخطط للذهاب إلى السينما غداً.", promptArFull: "كنا نخطط للذهاب إلى السينما غداً.", options: ["are", "were", "will"], answer: 1, explainAr: "للتلطيف نستخدم صيغة الماضي: We were planning." },
          { type: "fill", prompt: "___, the food was salty.", promptAr: "___، كان الطعام مالحاً.", promptArFull: "للأسف، كان الطعام مالحاً.", options: ["Unfortunate", "Fortunately", "Unfortunately"], answer: 2, explainAr: "ظرف الموقف Unfortunately (للأسف) يخفّف الخبر السيئ. Fortunately تعني «لحسن الحظ» ولا تناسب المعنى." },
          { type: "truefalse", prompt: "To be tactful, we say exactly what we think in a direct and negative way.", promptAr: "لكي نكون لبقين، نقول ما نفكر فيه تماماً بطريقة مباشرة وسلبية.", answer: false, explainAr: "خطأ: اللباقة تعني تخفيف الرسالة (soften a message) وتجنب الكلام السلبي المباشر." },
        ],
